<script setup>
import { computed, ref } from 'vue'; import QuestionCard from '../components/QuestionCard.vue'; import questions from '../data/questions.json'; import { getStorage, KEYS, getBookmarks } from '../utils/storage'
const search=ref(''), cat=ref('Semua'), sub=ref('Semua'), diff=ref('Semua'), status=ref('Semua'), active=ref(null)
const cats=['Semua',...new Set(questions.map(q=>q.kategori))]; const subs=computed(()=>['Semua',...new Set(questions.filter(q=>cat.value==='Semua'||q.kategori===cat.value).map(q=>q.subkategori))])
const answered=()=>getStorage(KEYS.history,[]); const filtered=computed(()=>questions.filter(q=>{const h=answered().filter(a=>a.questionId===q.id); return (!search.value||`${q.pertanyaan} ${q.subkategori} ${q.tags.join(' ')}`.toLowerCase().includes(search.value.toLowerCase()))&&(cat.value==='Semua'||q.kategori===cat.value)&&(sub.value==='Semua'||q.subkategori===sub.value)&&(diff.value==='Semua'||q.tingkat_kesulitan===diff.value)&&(status.value==='Semua'||(status.value==='Belum dijawab'&&!h.length)||(status.value==='Pernah benar'&&h.some(a=>a.correct))||(status.value==='Pernah salah'&&h.some(a=>!a.correct))||(status.value==='Bookmark'&&getBookmarks().includes(q.id)))}))
</script>
<template><section class="page"><h1>Bank Soal</h1><div class="toolbar card"><input v-model="search" placeholder="Search soal, tag, pembahasan..."/><select v-model="cat"><option v-for="x in cats" :key="x">{{ x }}</option></select><select v-model="sub"><option v-for="x in subs" :key="x">{{ x }}</option></select><select v-model="diff"><option>Semua</option><option>Mudah</option><option>Sedang</option><option>Sulit</option></select><select v-model="status"><option>Semua</option><option>Belum dijawab</option><option>Pernah benar</option><option>Pernah salah</option><option>Bookmark</option></select></div><p class="subtle">{{ filtered.length }} soal ditemukan. Mulai latihan dari hasil filter dapat dilakukan dengan memilih soal dan meninjau pembahasannya.</p><div class="bank-list"><article v-for="q in filtered" :key="q.id" class="card mini" @click="active=q"><b>{{ q.id }}</b><span>{{ q.kategori }} • {{ q.subkategori }}</span><p>{{ q.pertanyaan }}</p></article></div><QuestionCard v-if="active" :question="active" :number="1" :total="1" :selected="active.jawaban_benar" show-answer @finish="active=null" @next="active=null" @prev="active=null"/></section></template>
